// Every branch arrives here with { reply } and maybe booking_status / ticket_id.
const ctx = $('Build Context').first().json;
const ai = $('Validate AI Output').isExecuted ? $('Validate AI Output').first().json : {};
const cur = $json;
const language = ai.language || (/[؀-ۿ]/.test(ctx.text) ? 'ar' : 'en');
const text = String(cur.reply || '').trim() || (language === 'ar' ? 'شكرًا لرسالتك! هنرد عليك قريب.' : 'Thanks for your message! We will get back to you shortly.');
const route = ai.route || cur.route || 'unsupported';
const ticket_id = cur.ticket_id || '';

// What we learned about the customer in this turn
let phone = ctx.stored_phone, name = ctx.stored_name || ctx.customer_name;
if ($('Validate Booking').isExecuted) {
  const b = $('Validate Booking').first().json;
  if (/^01[0125]\d{8}$/.test(b.phone)) phone = b.phone;
  if (b.name) name = b.name;
}
const handoff = route === 'handoff';
return [{ json: {
  channel: ctx.channel, recipient_id: ctx.channel_user_id, customer_id: ctx.customer_id, text,
  route, intent: ai.intent || '', language, booking_status: cur.booking_status || '', ticket_id,
  customer_update: {
    name, phone, language,
    mode: handoff ? 'human' : ctx.mode,
    open_ticket_id: handoff ? ticket_id : ctx.open_ticket_id,
  },
}}];

// One pipeline for three sources: crashed executions, errors reported on purpose, and failed heartbeats.
const cfg = $('Get Config').first().json;
let e;
if ($('Error Trigger').isExecuted) {
  const d = $('Error Trigger').first().json;
  e = { workflow: d.workflow?.name || 'unknown', node: d.execution?.lastNodeExecuted || d.execution?.error?.node?.name || '',
    message: d.execution?.error?.message || d.trigger?.error?.message || 'Unknown error',
    execution_id: d.execution?.id || '', execution_url: d.execution?.url || '', severity: '', error_type: '' };
} else if ($('Report Handled Error').isExecuted) {
  const d = $('Report Handled Error').first().json;
  e = { workflow: d.workflow, node: d.node, message: d.message, execution_id: '', execution_url: '',
    severity: d.severity || '', error_type: d.error_type || '' };
} else {
  e = { ...$('Heartbeat Failed').first().json };
}
const msg = String(e.message || '');
const rules = [
  ['auth', 'critical', /401|403|unauthori[sz]ed|invalid.*token|access token|oauth|credential|permission/i],
  ['rate_limit', 'warning', /429|rate.?limit|quota|too many requests/i],
  ['network', 'warning', /ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|timeout|socket hang up|50[234]/i],
  ['ai_output', 'warning', /parse|json|output parser|schema|could not.*format/i],
  ['config', 'critical', /^Config:|is empty/i],
  ['validation', 'info', /^Invalid input|^Router: (empty|missing)/i],
  ['delivery', 'error', /Delivery failed/i],
  ['google_api', 'error', /google|sheets|spreadsheet|drive/i],
  ['messaging_api', 'error', /telegram|graph\.facebook|graph\.instagram|whatsapp/i],
];
let type = e.error_type, severity = e.severity;
if (!type) { const hit = rules.find(([, , re]) => re.test(msg)); type = hit ? hit[0] : 'unknown'; if (!severity) severity = hit ? hit[1] : 'error'; }
if (!severity) severity = 'error';
const now = DateTime.now().setZone(cfg.TIMEZONE);
return [{ json: {
  timestamp: now.toISO(),
  error_id: `E-${now.toFormat('yyMMddHHmmss')}-${Math.random().toString(36).slice(2, 5).toUpperCase()}`,
  workflow: e.workflow, node: e.node, error_type: type, severity, message: msg.slice(0, 500),
  execution_id: String(e.execution_id || ''), execution_url: e.execution_url || '',
  fingerprint: `${e.workflow}|${e.node}|${type}`,
}}];

// Alert storms help nobody: one alert per fingerprint per ALERT_THROTTLE_MIN minutes.
const cfg = $('Get Config').first().json;
const e = $('Classify Error').first().json;
const win = Number(cfg.ALERT_THROTTLE_MIN) || 15;
const now = DateTime.fromISO(e.timestamp);
const recent = $input.all().map(i => i.json).filter(r => r.fingerprint === e.fingerprint && r.alerted === 'yes'
  && now.diff(DateTime.fromISO(String(r.timestamp)), 'minutes').minutes < win);
const alerted = e.severity === 'info' ? 'no' : recent.length ? 'suppressed' : 'yes';
return [{ json: { ...e, alerted } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cfg = $('Get Config').first().json;
const e = $('Throttle Check').first().json;
const icon = { critical: '🛑', error: '❗', warning: '⚠️' }[e.severity] || '❗';
const link = e.execution_url ? `\n🔗 ${esc(e.execution_url)}` : '';
return [{ json: { ...e, chat_id: cfg.ADMIN_CHAT_ID || cfg.STAFF_CHAT_ID, admin_email: cfg.ADMIN_EMAIL,
  text: `${icon} <b>${esc(e.severity.toUpperCase())} · ${esc(e.error_type)}</b>\n${esc(e.workflow)} → ${esc(e.node)}\n${esc(e.message)}\n🆔 ${esc(e.error_id)}${link}\n(similar alerts muted for ${cfg.ALERT_THROTTLE_MIN} min)` } }];

// Proves the full public path works: internet → ngrok → Docker → n8n.
const r = $json;
const body = typeof r.body === 'string' ? (() => { try { return JSON.parse(r.body); } catch { return {}; } })() : (r.body || {});
const healthy = r.statusCode === 200 && body.status === 'ok';
return [{ json: { healthy, status: r.statusCode ?? 'no response', detail: r.error?.message || JSON.stringify(body).slice(0, 120) } }];

const cfg = $('Get Config (Digest)').first().json;
const now = DateTime.now().setZone(cfg.TIMEZONE);
const since = now.minus({ hours: 24 });
const recent = (rows, field) => rows.map(i => i.json).filter(r => { const d = DateTime.fromISO(String(r[field] || '')); return d.isValid && d >= since; });
const errors = recent($('Read Error Log').all(), 'timestamp');
const allTickets = $('Read All Tickets').all().map(i => i.json).filter(r => r.ticket_id && r.channel !== 'test');
const newTickets = recent($('Read All Tickets').all(), 'created_at').filter(r => r.channel !== 'test');
const msgs = recent($('Read Conversations').all(), 'timestamp').filter(r => r.channel !== 'test');
const count = (rows, key) => rows.reduce((a, r) => (a[r[key] || 'n/a'] = (a[r[key] || 'n/a'] || 0) + 1, a), {});
const fmt = o => Object.entries(o).map(([k, v]) => `${k}: ${v}`).join(', ') || 'none';
const inbound = msgs.filter(r => r.direction === 'in');
const open = allTickets.filter(r => r.status !== 'resolved');
const breached = allTickets.filter(r => Number(r.escalation_count) > 0 && r.status !== 'resolved');
const stats = {
  messages_in: inbound.length, by_channel: fmt(count(inbound, 'channel')), by_route: fmt(count(inbound, 'route')),
  new_tickets: newTickets.length, open_tickets: open.length, sla_breached_open: breached.length,
  errors: errors.length, errors_by_type: fmt(count(errors, 'error_type')),
  critical: errors.filter(r => r.severity === 'critical').length,
};
const row = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#555">${k}</td><td style="padding:4px 0"><b>${v}</b></td></tr>`;
const html = `<h2 style="font-family:sans-serif">Nile Smile support digest · ${now.toFormat('d LLL yyyy')}</h2>
<table style="font-family:sans-serif;font-size:14px">${row('Customer messages (24h)', stats.messages_in)}${row('By channel', stats.by_channel)}${row('By route', stats.by_route)}${row('New tickets', stats.new_tickets)}${row('Open tickets', stats.open_tickets)}${row('Open with SLA breach', stats.sla_breached_open)}${row('Errors (24h)', stats.errors)}${row('Errors by type', stats.errors_by_type)}${row('Critical errors', stats.critical)}</table>
<p style="font-family:sans-serif;font-size:12px;color:#888">Sent by NSD 4 · Ops & Monitoring. Test traffic excluded.</p>`;
const text = `📊 Daily digest ${now.toFormat('d LLL')}\nMessages: ${stats.messages_in} (${stats.by_channel})\nNew tickets: ${stats.new_tickets} · Open: ${stats.open_tickets} · SLA breached: ${stats.sla_breached_open}\nErrors: ${stats.errors} (${stats.errors_by_type})`;
return [{ json: { ...stats, html, text, chat_id: cfg.ADMIN_CHAT_ID || cfg.STAFF_CHAT_ID, email: cfg.ADMIN_EMAIL, subject: `[Nile Smile] Daily support digest · ${now.toFormat('d LLL yyyy')}` } }];

// A breach = an open ticket nobody took before its SLA, or a taken ticket with no reply after 2x the SLA.
// We re-alert at most every REESCALATE_MIN minutes per ticket.
const cfg = $('Get Config (SLA)').first().json;
const now = DateTime.now().setZone(cfg.TIMEZONE);
const gap = Number(cfg.REESCALATE_MIN) || 30;
const out = [];
for (const t of $input.all().map(i => i.json)) {
  if (!t.ticket_id || !['open', 'in_progress'].includes(t.status) || t.channel === 'test') continue;
  const created = DateTime.fromISO(String(t.created_at));
  const due = DateTime.fromISO(String(t.sla_due_at));
  if (!created.isValid || !due.isValid) continue;
  const notTaken = t.status === 'open' && now > due;
  const noReply = t.status === 'in_progress' && !t.first_response_at && now > due.plus(due.diff(created));
  if (!notTaken && !noReply) continue;
  const last = t.last_escalated_at ? DateTime.fromISO(String(t.last_escalated_at)) : null;
  if (last?.isValid && now.diff(last, 'minutes').minutes < gap) continue;
  const level = (Number(t.escalation_count) || 0) + 1;
  out.push({ json: { ...t, level, overdue_min: Math.round(now.diff(due, 'minutes').minutes),
    problem: notTaken ? 'Not taken yet' : `Taken by ${t.assigned_to} but no reply yet`,
    email_manager: level >= 2 || t.priority === 'urgent', now: now.toISO() } });
}
return out;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cfg = $('Get Config (SLA)').first().json;
const t = $json;
const text = `⏰ <b>SLA breach · level ${t.level}</b>
<b>${esc(t.ticket_id)}</b> · ${esc(t.priority)} · ${esc(t.type)}
` +
  `👤 ${esc(t.customer_name)} (${esc(t.channel)})
${esc(t.problem)}, overdue by ${t.overdue_min} min.

` +
  `📝 ${esc(t.summary)}

Reply: <code>/reply ${esc(t.ticket_id)} your message</code>`;
return [{ json: { ...t, chat_id: cfg.STAFF_CHAT_ID, alert_text: text } }];

// The Drive node exported the Google Doc as plain text into a binary file. Read it as a string.
// Refuse to wipe a working knowledge base with an empty or broken document.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const content = buffer.toString('utf8').replace(/^\uFEFF/, '');
if (content.trim().length < 200) throw new Error(`KB document looks empty (${content.length} chars). Store not updated.`);
return [{ json: { content, chars: content.length, loaded_at: $now.toISO() } }];

// Each run uses fresh fake customers so earlier runs (human mode, history) cannot affect results.
const run = 'run' + DateTime.now().toFormat('MMddHHmm');
return $input.all().filter(i => i.json.test_id && i.json.message).map(i => ({ json: { ...i.json, run_id: run } }));

const t = $('Loop Over Tests').first().json;
const r = $json;
let actual = r.route || 'error';
if (actual === 'booking') actual = { incomplete: 'booking_incomplete', invalid: 'booking_invalid' }[r.booking_status] || 'booking';
const passed = actual === t.expected_route;
return [{ json: { test_id: t.test_id, actual_intent: r.intent || '', actual_route: actual,
  actual_reply: String(r.reply || r.error || '').slice(0, 500), passed: passed ? 'yes' : 'no', run_at: $now.toISO() } }];

const rows = $input.all().map(i => i.json);
const passed = rows.filter(r => r.passed === 'yes').length;
return [{ json: { total: rows.length, passed, failed: rows.length - passed,
  pass_rate: rows.length ? Math.round(passed * 100 / rows.length) + '%' : 'n/a',
  failures: rows.filter(r => r.passed !== 'yes').map(r => `${r.test_id}: got ${r.actual_route}`) } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cfg = $('Config Values').first().json;
const p = $('When Called').first().json.payload || {};
if (!cfg.STAFF_CHAT_ID) throw new Error('Config: STAFF_CHAT_ID is empty. Send /groupid in the staff group and paste the ID into NSD 3 · Delivery & Staff Desk (Config Values node).');
const icon = { urgent: '🚨', high: '🔴', normal: '🟡' }[p.priority] || '🟡';
const test = p.channel === 'test' ? '[TEST] ' : '';
const due = DateTime.fromISO(String(p.sla_due_at)).setZone(cfg.TIMEZONE);
const text = [
  `${icon} <b>${test}New ${esc(String(p.type).replace('_', ' '))} ticket ${esc(p.ticket_id)}</b>`,
  `👤 ${esc(p.customer_name)} · ${esc(p.channel)} · ${esc(p.language)}`,
  `Priority: <b>${esc(p.priority)}</b> · Urgency: ${esc(p.urgency)} · Sentiment: ${esc(p.sentiment)}`,
  `SLA: take before ${due.isValid ? due.toFormat('HH:mm') : '-'}`,
  '',
  `📝 ${esc(p.summary)}`,
  `💬 "${esc(String(p.last_customer_message || '').slice(0, 400))}"`,
  '',
  `Reply: <code>/reply ${esc(p.ticket_id)} your message</code>`,
].join('\n');
return [{ json: { chat_id: cfg.STAFF_CHAT_ID, text, ticket_id: p.ticket_id } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cfg = $('Config Values').first().json;
const p = $('When Called').first().json.payload || {};
if (!cfg.STAFF_CHAT_ID) throw new Error('Config: STAFF_CHAT_ID is empty');
const text = `💬 <b>${esc(p.ticket_id)}</b> · ${esc(p.customer_name)} (${esc(p.channel)}) wrote:\n` +
  `"${esc(String(p.text).slice(0, 1500))}"\n\nReply: <code>/reply ${esc(p.ticket_id)} your message</code>`;
return [{ json: { chat_id: cfg.STAFF_CHAT_ID, text } }];

const p = $('When Called').first().json.payload || {};
const [action, ticket_id] = String(p.data || '').split(':');
if (!['take', 'resolve'].includes(action) || !ticket_id) throw new Error('Unknown button data: ' + p.data);
const staff = p.from_username ? '@' + p.from_username : (p.from_name || 'staff');
return [{ json: { action, ticket_id, staff, callback_query_id: p.callback_query_id,
  chat_id: p.chat_id, message_id: p.message_id, message_text: p.message_text || '' } }];

// Business rules for buttons: a resolved ticket is closed, and a taken ticket belongs to one person.
const cfg = $('Config Values').first().json;
const btn = $('Parse Button').first().json;
const t = $input.all().map(i => i.json).find(r => r.ticket_id === btn.ticket_id);
const now = DateTime.now().setZone(cfg.TIMEZONE);
const stamp = now.toFormat('HH:mm');
if (!t) return [{ json: { ...btn, outcome: 'not_found', toast: `Ticket ${btn.ticket_id} not found` } }];
if (t.status === 'resolved') return [{ json: { ...btn, ticket: t, outcome: 'already_resolved', toast: `${t.ticket_id} is already resolved` } }];
if (btn.action === 'take') {
  if (t.status === 'in_progress' && t.assigned_to && t.assigned_to !== btn.staff)
    return [{ json: { ...btn, ticket: t, outcome: 'already_taken', toast: `Already taken by ${t.assigned_to}` } }];
  return [{ json: { ...btn, ticket: t, outcome: 'take', toast: `You took ${t.ticket_id}`,
    new_text: `${btn.message_text}\n\n✋ Taken by ${btn.staff} at ${stamp}`,
    update: { status: 'in_progress', assigned_to: btn.staff, taken_at: t.taken_at || now.toISO() } } }];
}
return [{ json: { ...btn, ticket: t, outcome: 'resolve', toast: `${t.ticket_id} resolved`,
  new_text: `${btn.message_text}\n\n✅ Resolved by ${btn.staff} at ${stamp}`,
  update: { status: 'resolved', assigned_to: t.assigned_to || btn.staff, resolved_at: now.toISO() } } }];

const p = $('When Called').first().json.payload || {};
const text = String(p.text || '').trim();
const staff = p.from_username ? '@' + p.from_username : (p.from_name || 'staff');
const m = text.match(/^\/reply(?:@\w+)?\s+(T-[A-Za-z0-9-]+)\s+([\s\S]+)$/i);
if (m) return [{ json: { valid: true, ticket_id: m[1].toUpperCase(), reply: m[2].trim(), staff,
  chat_id: p.chat_id, message_id: p.message_id } }];
return [{ json: { valid: false, chat_id: p.chat_id, message_id: p.message_id,
  help: 'Usage: /reply T-261029-AB12 Your message to the customer' } }];

const cmd = $('Parse Command').first().json;
const t = $input.all().map(i => i.json).find(r => r.ticket_id === cmd.ticket_id);
if (!t) return [{ json: { ...cmd, ok: false, reason: `Ticket ${cmd.ticket_id} not found.` } }];
if (t.status === 'resolved') return [{ json: { ...cmd, ok: false, reason: `${t.ticket_id} is already resolved. The customer is back with the AI assistant.` } }];
return [{ json: { ...cmd, ok: true, ticket: t } }];

// Guard the send step: every channel has its own limits and required IDs.
const cfg = $('Config Values').first().json;
const m = $('When Called').first().json.payload || {};
const limits = { telegram: 4000, whatsapp: 4000, messenger: 1900, instagram: 1000, test: 4000 };
const channel = String(m.channel || '').toLowerCase().trim();
if (!limits[channel]) throw new Error(`Router: unsupported channel "${channel}"`);
if (!m.recipient_id) throw new Error('Router: missing recipient_id');
let text = String(m.text || '').trim();
if (!text) throw new Error('Router: empty text');
if (channel === 'whatsapp' && !cfg.WA_PHONE_NUMBER_ID) throw new Error('Config: WA_PHONE_NUMBER_ID is empty');
if (channel === 'instagram') {
  // Instagram counts bytes, and Arabic letters take 2 bytes each
  while (Buffer.byteLength(text, 'utf8') > 990) text = text.slice(0, -5);
} else if (text.length > limits[channel]) {
  text = text.slice(0, limits[channel] - 1) + '…';
}
return [{ json: {
  channel, recipient_id: String(m.recipient_id), text,
  customer_id: m.customer_id || '', ticket_id: m.ticket_id || '', sender: m.sender || 'ai',
  graph: cfg.GRAPH_VERSION, wa_phone_id: cfg.WA_PHONE_NUMBER_ID,
}}];

// All four send nodes share this error branch. Turn the raw error into one readable line.
const out = $('Validate Outbound').first().json;
const e = $json.error || {};
const detail = e.description || e.message || (typeof e === 'string' ? e : JSON.stringify(e));
let hint = '';
if (/131047|re-engage|24 hour|outside.*window/i.test(detail)) hint = ' (customer is outside the 24-hour messaging window)';
if (/131030|not in allowed list|recipient phone number not/i.test(detail)) hint = ' (add this number to the test recipients list in Meta)';
if (/OAuth|access token|190/i.test(detail)) hint = ' (token expired or invalid: update the Meta credential)';
return [{ json: {
  status: 'failed', channel: out.channel, provider_message_id: '',
  error: String(detail).slice(0, 400) + hint, sent_at: $now.toISO(),
}}];
